/** base64 -> ArrayBuffer, using only APIs both Node and workerd expose. */
function decode(b64: string): ArrayBuffer {
  const bin = atob(b64);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return bytes.buffer;
}

export const spaceGroteskRegular = () => decode(REGULAR_B64);
export const spaceGroteskBold = () => decode(BOLD_B64);
